<script lang="ts">
 export let admin=true;
 import {onMount} from 'svelte';import {acquisition,requestStates,type DownloadRequest} from './acquisition';import type {Work} from './types';import {workCard,type Card} from './experience';
 export let token:string;export let refresh:()=>Promise<void>;export let open:(card:Card)=>void;export let settings:()=>void;
 let requests:DownloadRequest[]=[];let busy=false;let error='';let loading=true;let alive=true;let notice='';let known=new Map<string,number>();let first=true;
 async function load(){try{const all=await acquisition<DownloadRequest[]>(token,'requests');if(!alive)return;const arrivals=all.filter(r=>r.local>(known.get(r.id)??0));if(!first&&arrivals.length){notice=arrivals.map(r=>`« ${r.title} » est disponible${r.state==='partial'?' en partie':''}.`).join(' ');await refresh();}known=new Map(all.map(r=>[r.id,r.local]));first=false;requests=all;error='';}catch(e){if(alive)error=e instanceof Error?e.message:'Suivi indisponible.';}finally{if(alive)loading=false;}}
 async function sync(){busy=true;error='';try{await acquisition(token,'sync','POST',{});await load();await refresh();}catch(e){error=e instanceof Error?e.message:'Vérification impossible.';}finally{busy=false;}}
 async function show(id:string){try{const r=await fetch('/api/v1/discovery/works/'+id);const data=await r.json();if(!r.ok)throw new Error(data.error);open(workCard(data.work as Work));}catch(e){error=e instanceof Error?e.message:'Fiche indisponible.';}}
 onMount(()=>{void load();const interval=setInterval(()=>{if(!busy&&!document.hidden)void load();},15000);return()=>{alive=false;clearInterval(interval);};});
</script>
<section class="download-requests"><div class="page-heading"><span class="eyebrow">DE L’ENVIE À LA COLLECTION</span><h1>Vos demandes</h1><p>Le suivi continue tant que le serveur Mosaune est ouvert. Les services gèrent les téléchargements.</p></div><div class="content-actions"><button class="secondary" disabled={!admin||busy} onclick={sync}>{busy?'Vérification…':'Actualiser le suivi'}</button><button class="text-action" disabled={!admin} onclick={settings}>Configurer les services</button></div>
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}{#if error}<p class="playback-error" role="alert">{error}</p>{/if}
 {#if loading}<p role="status">Chargement…</p>{:else if !requests.length}<div class="download-empty"><h2>Votre prochaine découverte commence sur une fiche.</h2><p>Choisissez un film ou une série, puis « Demander le téléchargement ». Pour une seule saison, ouvrez-la sur la fiche de la série.</p></div>{/if}
 {#each requests as r (r.id)}<article class="download-item"><div class="download-heading"><button class="download-title" onclick={()=>show(r.workId)}>{r.title}{r.kind==='series'?r.season<0?' · Série entière':` · Saison ${r.season}`:''} <span>↗</span></button><span class="download-badge" class:ready={r.state==='available'}>{requestStates[r.state]||r.state}</span></div><p>{r.message}</p>{#if r.state==='downloading'&&r.progress>0}<progress max="100" value={r.progress} aria-label={`Téléchargement de ${r.title}`}></progress><small>{Math.round(r.progress)} % de la file active</small>{/if}{#if r.kind==='series'&&r.total>0}<p class="folder-help">{r.local} / {r.total} épisodes référencés disponibles ici · {r.imported} importés dans Sonarr</p>{/if}<small>{r.connector==='radarr'?'Radarr':'Sonarr'} · Demandé le {new Date(r.created*1000).toLocaleDateString('fr')} · Suivi {r.updated?new Date(r.updated*1000).toLocaleTimeString('fr',{hour:'2-digit',minute:'2-digit'}):'en cours'}</small></article>{/each}
</section>
